/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: db, request, clipForm
 *   Constants: admin, listener, track, videoKey, objects, storage, flags, previous, path
 *   Variables: harness, server, base, adminToken, userToken, versionCounter, deletes
 * Tests
 *   - motion preview management is administrator-only, viewer-bound, and hidden while disabled
 *   - an uploaded preview is stored, bound to the active Video, and served only while that Video is active
 *   - removing a preview deletes its exact version and requires the current revision
 *   - once MediaTrack deletion begins, a preview removal never changes the record its fence compares
 *   - malformed uploads and inputs are refused before any storage write
 * @end-catalog */

import assert from 'node:assert/strict';
import express from 'express';
import type { Server } from 'node:http';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';

import { resolveMotionPreview } from '../../src/controllers/motionPreviewController';
import { getDb } from '../../src/infrastructure/database';
import { createAdminMotionPreviewRouter } from '../../src/routes/adminMotionPreviewRoutes';
import { createSession } from '../../src/services/auth/authSessionService';
import type { MotionPreviewLifecycleDependencies } from '../../src/services/media/motionPreviewLifecycleService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness;
let server: Server;
let base = '';
let adminToken = '';
let userToken = '';
const admin = new ObjectId();
const listener = new ObjectId();
const track = new ObjectId();
const videoKey = `video/${track}/${new ObjectId()}`;
const objects = new Map<string, { versionId: string; etag: string; metadata: Record<string, string> }>();
let versionCounter = 0;
let deletes: string[] = [];

/** Injected S3 boundary; the database lifecycle is real. */
const storage: Partial<MotionPreviewLifecycleDependencies> = {
    putObject: async (key, _file, metadata) => {
        const versionId = `v${++versionCounter}`;
        const etag = `"etag-${versionCounter}"`;
        objects.set(key, { versionId, etag, metadata });
        return { ETag: etag, VersionId: versionId };
    },
    headObject: async (key) => {
        const object = objects.get(key);
        return object ? { ETag: object.etag, VersionId: object.versionId, Metadata: object.metadata } : null;
    },
    deleteObject: async (key, versionId) => {
        deletes.push(`${key}@${versionId}`);
        if (objects.get(key)?.versionId === versionId) objects.delete(key);
    },
    validate: async (file) => ({ durationMs: 6_000, width: 854, height: 480, byteLength: file.size, sha256: 'b'.repeat(64) })
};

const flags = ['FINITUDE_MOTION_PREVIEWS_ENABLED', 'S3_BUCKET_NAME'] as const;
const previous = Object.fromEntries(flags.map((key) => [key, process.env[key]]));
const db = () => getDb()!;
const path = `/api/admin/v1/catalog/audioTrack/${track}/motion-preview`;

const request = (method: string, token = adminToken, viewer = String(admin), body?: BodyInit) => fetch(base + path, {
    method,
    headers: {
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        'X-Finitude-Account-Viewer': viewer,
        ...(typeof body === 'string' ? { 'Content-Type': 'application/json' } : {})
    },
    ...(body ? { body } : {})
});

const clipForm = (sourceToken: string, expectedRevision: number) => {
    const form = new FormData();
    form.set('sourceToken', sourceToken);
    form.set('expectedRevision', String(expectedRevision));
    form.set('motionPreviewFile', new Blob([Buffer.alloc(2048, 7)], { type: 'video/mp4' }), 'preview.mp4');
    return form;
};

before(async () => {
    harness = await startMongoReplicaSet('archtree-motion-preview-test');
    const app = express();
    app.use('/api/admin/v1', createAdminMotionPreviewRouter(storage));
    server = await new Promise((resolve) => { const listening = app.listen(0, '127.0.0.1', () => resolve(listening)); });
    const address = server.address();
    assert.ok(address && typeof address !== 'string');
    base = `http://127.0.0.1:${address.port}`;
});

beforeEach(async () => {
    for (const collection of ['users', 'authSessions', 'audioTracks']) await db().collection(collection).deleteMany({});
    process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = 'true';
    process.env.S3_BUCKET_NAME = 'synthetic-motion-preview-bucket';
    const adminUser = { _id: admin, role: 'admin', emailVerified: true, email: 'preview-admin@example.test' };
    const ordinary = { _id: listener, role: 'user', emailVerified: true, email: 'preview-user@example.test' };
    await db().collection('users').insertMany([adminUser, ordinary]);
    adminToken = (await createSession(adminUser)).accessToken;
    userToken = (await createSession(ordinary)).accessToken;
    await db().collection('audioTracks').insertOne({
        _id: track, title: 'Synthetic Video', mediaType: 'video', s3Key: videoKey, contentType: 'video/mp4',
        uploadStatus: 'ready', publicationStatus: 'ready', createdBy: String(admin), duration: '01:00',
        artistIds: [], genres: [], playlistReferenceRevision: 0, contentReferenceRevision: 0
    });
    objects.clear();
    deletes = [];
});

after(async () => {
    await new Promise<void>((resolve) => server?.close(() => resolve()));
    await harness?.stop();
    for (const key of flags) {
        if (previous[key] === undefined) delete process.env[key];
        else process.env[key] = previous[key];
    }
});

test('motion preview management is administrator-only, viewer-bound, and hidden while disabled', async () => {
    assert.equal((await request('GET', '')).status, 401);
    assert.equal((await request('GET', userToken, String(listener))).status, 403);
    // A browser cookie session is fenced to the current viewer; a Bearer request is bound by its token.
    const cookieRead = (viewer: string) => fetch(base + path, {
        headers: { Cookie: `session_token=${encodeURIComponent(adminToken)}`, 'X-Finitude-Account-Viewer': viewer }
    });
    assert.equal((await cookieRead(String(listener))).status, 409);
    assert.equal((await cookieRead(String(admin))).status, 200);
    assert.equal((await request('GET', adminToken, String(listener))).status, 200);
    process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = 'false';
    const disabled = await request('GET');
    assert.equal(disabled.status, 404);
    assert.deepEqual(await disabled.json(), { code: 'ADMIN_MOTION_PREVIEW_DISABLED' });
    process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = 'true';
    const enabled = await request('GET');
    assert.equal(enabled.status, 200);
    assert.match(enabled.headers.get('cache-control')!, /no-store/);
});

test('an uploaded preview is stored, bound to the active Video, and served only while that Video is active', async () => {
    const status = await (await request('GET')).json();
    assert.equal(status.eligible, true);
    assert.equal(JSON.stringify(status).includes('video/'), false);

    const stale = await request('POST', adminToken, String(admin), clipForm('0'.repeat(32), status.revision));
    assert.equal(stale.status, 409);
    assert.equal(objects.size, 0);

    const created = await request('POST', adminToken, String(admin), clipForm(status.sourceToken, status.revision));
    assert.equal(created.status, 201);
    const body = await created.json();
    assert.match(body.revision, /^pv_[0-9a-f]{32}$/);
    const stored = await db().collection('audioTracks').findOne({ _id: track });
    assert.equal(stored?.motionPreview.active.source.s3Key, videoKey);
    assert.equal(objects.size, 1);

    // The real public read path finds the published track with its full preview record.
    const signal = new AbortController().signal;
    const visible = await resolveMotionPreview(String(track), undefined, signal, undefined, {
        headObject: async () => ({ ContentLength: 2048, ETag: stored!.motionPreview.active.etag, VersionId: stored!.motionPreview.active.versionId })
    });
    assert.equal(visible.status, 'ready');

    // Replacing the Video hides the preview at once, before any cleanup runs.
    await db().collection('audioTracks').updateOne({ _id: track }, { $set: { s3Key: `video/${track}/${new ObjectId()}` } });
    assert.equal((await resolveMotionPreview(String(track), undefined, signal, undefined, {
        headObject: async () => { throw new Error('storage must not be reached'); }
    })).status, 'notFound');
});

test('removing a preview deletes its exact version and requires the current revision', async () => {
    const status = await (await request('GET')).json();
    await request('POST', adminToken, String(admin), clipForm(status.sourceToken, status.revision));
    const current = await (await request('GET')).json();

    assert.equal((await request('DELETE', adminToken, String(admin), JSON.stringify({ expectedRevision: 0 }))).status, 409);
    const removed = await request('DELETE', adminToken, String(admin), JSON.stringify({ expectedRevision: current.revision }));
    assert.equal(removed.status, 200);
    assert.deepEqual(await removed.json(), { cleanupPending: false });
    assert.equal(objects.size, 0);
    assert.equal(deletes.length, 1);
    const stored = await db().collection('audioTracks').findOne({ _id: track });
    assert.equal(stored?.motionPreview.active, null);
    assert.equal(stored?.motionPreview.cleanup, null);
});

test('once MediaTrack deletion begins, a preview removal never changes the record its fence compares', async () => {
    const status = await (await request('GET')).json();
    await request('POST', adminToken, String(admin), clipForm(status.sourceToken, status.revision));
    const current = await (await request('GET')).json();
    await db().collection('audioTracks').updateOne({ _id: track }, { $set: { uploadStatus: 'deleting' } });
    const fenced = (await db().collection('audioTracks').findOne({ _id: track }))!.motionPreview;

    const removed = await request('DELETE', adminToken, String(admin), JSON.stringify({ expectedRevision: current.revision }));
    assert.equal(removed.status, 409);
    assert.deepEqual((await db().collection('audioTracks').findOne({ _id: track }))!.motionPreview, fenced);
    assert.equal(objects.size, 1);
    assert.deepEqual(deletes, []);
});

test('malformed uploads and inputs are refused before any storage write', async () => {
    const status = await (await request('GET')).json();
    const missingFile = new FormData();
    missingFile.set('sourceToken', status.sourceToken);
    missingFile.set('expectedRevision', String(status.revision));
    assert.equal((await request('POST', adminToken, String(admin), missingFile)).status, 400);
    const extraField = clipForm(status.sourceToken, status.revision);
    extraField.set('s3Key', 'motion-preview/forged');
    assert.equal((await request('POST', adminToken, String(admin), extraField)).status, 400);
    assert.equal((await request('DELETE', adminToken, String(admin), JSON.stringify({ expectedRevision: 'x' }))).status, 400);
    assert.equal(objects.size, 0);
});
